package com.expecteddrops.stats;

/**
 * Probability helpers. Each kill is an independent roll, so the number of drops after
 * n kills is binomial; with the small rates bosses use, Poisson with the same mean is
 * an excellent approximation and lets us combine several items into one "any" row.
 */
public final class DropMath
{
	private DropMath()
	{
	}

	/** Parses "1/50", "3/512" or a plain decimal like "0.02". Returns 0 for null or blank. */
	public static double parseRate(String rate)
	{
		if (rate == null || rate.trim().isEmpty())
		{
			return 0;
		}
		String s = rate.replace(",", "").trim();
		int slash = s.indexOf('/');
		if (slash < 0)
		{
			return Double.parseDouble(s);
		}
		double num = Double.parseDouble(s.substring(0, slash).trim());
		double den = Double.parseDouble(s.substring(slash + 1).trim());
		if (den <= 0)
		{
			throw new IllegalArgumentException("Bad rate: " + rate);
		}
		return num / den;
	}

	/** Chance of at least one drop in {@code kc} kills at {@code rate} per kill. */
	public static double chanceAtLeastOne(double rate, long kc)
	{
		if (kc <= 0 || rate <= 0)
		{
			return 0;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return -Math.expm1(kc * Math.log1p(-rate));
	}

	/** Chance of at least one event when {@code expected} events are expected (Poisson). */
	public static double chanceAtLeastOne(double expected)
	{
		if (expected <= 0)
		{
			return 0;
		}
		return -Math.expm1(-expected);
	}

	/**
	 * How lucky a result is: the share of players who would have fewer drops than you,
	 * counting half of those with exactly as many (the "mid-p" percentile). 50% means
	 * perfectly average, above 50% means luckier than average. NaN when nothing is expected yet.
	 */
	public static double luckPercentile(int received, double expected)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return Double.NaN;
		}
		if (received < 0)
		{
			received = 0;
		}
		double logLambda = Math.log(expected);
		double logFactorial = 0;
		double below = 0;
		for (int j = 0; j < received; j++)
		{
			if (j > 0)
			{
				logFactorial += Math.log(j);
			}
			below += Math.exp(-expected + j * logLambda - logFactorial);
		}
		if (received > 0)
		{
			logFactorial += Math.log(received);
		}
		double equal = Math.exp(-expected + received * logLambda - logFactorial);
		double p = below + 0.5 * equal;
		return Math.max(0, Math.min(1, p));
	}

	/** Kills needed to reach {@code probability} chance of at least one drop. -1 if never. */
	public static long killsForChance(double rate, double probability)
	{
		if (rate <= 0 || probability <= 0)
		{
			return -1;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return (long) Math.ceil(Math.log1p(-probability) / Math.log1p(-rate));
	}

	/**
	 * A word for a luck percentile, from the player's point of view.
	 * Empty when there's nothing to judge yet.
	 */
	public static String verdict(double luck)
	{
		if (Double.isNaN(luck))
		{
			return "";
		}
		if (luck < 0.10)
		{
			return "Very dry";
		}
		if (luck < 0.35)
		{
			return "Dry";
		}
		if (luck <= 0.65)
		{
			return "On rate";
		}
		if (luck <= 0.90)
		{
			return "Spooned";
		}
		return "Very spooned";
	}

	/**
	 * Luck percentile for total value: the share of players with the same kills who got
	 * less GP from these items than you (ties count half). Rare, expensive items dominate
	 * value, so a formula would be misleading; instead we simulate the kills many times.
	 * Uses a fixed seed so the number doesn't jump around between refreshes.
	 *
	 * @param expected expected number of drops per item
	 * @param prices   price per item (0 for untradeables, which are skipped)
	 * @param received total value actually received
	 * @return percentile between 0 and 1, or NaN when nothing of value is expected yet
	 */
	public static double valueLuck(double[] expected, long[] prices, long received, int samples, long seed)
	{
		double total = 0;
		for (int i = 0; i < expected.length; i++)
		{
			if (prices[i] > 0)
			{
				total += expected[i] * prices[i];
			}
		}
		if (total <= 0)
		{
			return Double.NaN;
		}
		java.util.Random random = new java.util.Random(seed);
		double below = 0;
		for (int s = 0; s < samples; s++)
		{
			long value = 0;
			for (int i = 0; i < expected.length; i++)
			{
				if (prices[i] > 0 && expected[i] > 0)
				{
					value += poisson(random, expected[i]) * prices[i];
				}
			}
			if (value < received)
			{
				below += 1;
			}
			else if (value == received)
			{
				below += 0.5;
			}
		}
		return below / samples;
	}

	/** A random number of drops when {@code mean} are expected. */
	static long poisson(java.util.Random random, double mean)
	{
		if (mean > 30)
		{
			// normal approximation is accurate here and much faster
			return Math.max(0, Math.round(mean + Math.sqrt(mean) * random.nextGaussian()));
		}
		double limit = Math.exp(-mean);
		double product = random.nextDouble();
		long count = 0;
		while (product > limit)
		{
			product *= random.nextDouble();
			count++;
		}
		return count;
	}

	/** "1.24b", "345.6m", "12.3k" or "950" coins. */
	public static String formatGp(double gp)
	{
		double abs = Math.abs(gp);
		if (abs >= 1_000_000_000)
		{
			return String.format("%.2fb", gp / 1_000_000_000);
		}
		if (abs >= 1_000_000)
		{
			return String.format("%.1fm", gp / 1_000_000);
		}
		if (abs >= 1_000)
		{
			return String.format("%.1fk", gp / 1_000);
		}
		return String.format("%.0f", gp);
	}

	/** "1/181" style text for a per-kill rate. */
	public static String formatRate(double rate)
	{
		if (rate <= 0)
		{
			return "unknown";
		}
		double inverse = 1.0 / rate;
		if (inverse < 10)
		{
			return String.format("1/%.2f", inverse);
		}
		if (Math.abs(inverse - Math.rint(inverse)) < 0.05 || inverse >= 1000)
		{
			return String.format("1/%,d", Math.round(inverse));
		}
		return String.format("1/%,.1f", inverse);
	}
}

package com.expecteddrops.stats;

/**
 * Purple chances from raid points, using the formulas on the OSRS Wiki. Each method returns
 * your own expected number of uniques for one raid (for a single roll, that is the chance).
 */
public final class RaidChance
{
	/** Chambers of Xeric: every 8,676 team points is 1% for a unique. */
	public static final double COX_POINTS_PER_PERCENT = 8_676;
	/** One unique roll is capped at 570,000 points (65.7%); points above that roll again. */
	public static final int COX_POINTS_PER_ROLL = 570_000;
	/** At most six uniques per raid. */
	public static final int COX_MAX_ROLLS = 6;

	/** Tombs of Amascut: the chance to see a unique is capped at 55%. */
	public static final double TOA_MAX_CHANCE = 0.55;
	/** Uniques rolled below their minimum raid level are kept 1 time in 50. */
	public static final double TOA_LOW_LEVEL_KEEP = 1 / 50.0;

	private RaidChance()
	{
	}

	/**
	 * Expected uniques for the whole team in one Chambers raid: 1% per 8,676 points, each
	 * roll capped at 570,000 points (65.7%), with further points rolling for another unique.
	 */
	public static double coxTeamUniques(int teamPoints)
	{
		double uniques = 0;
		for (int roll = 0; roll < COX_MAX_ROLLS; roll++)
		{
			int points = Math.min(Math.max(teamPoints - roll * COX_POINTS_PER_ROLL, 0), COX_POINTS_PER_ROLL);
			uniques += points / COX_POINTS_PER_PERCENT / 100;
		}
		return uniques;
	}

	/**
	 * Your expected uniques for one Chambers raid. Each unique goes to a player with a
	 * chance equal to their share of the points. NaN when the points are unknown.
	 */
	public static double cox(int personalPoints, int teamPoints)
	{
		if (personalPoints <= 0)
		{
			return Double.NaN;
		}
		int team = Math.max(teamPoints, personalPoints);
		return coxTeamUniques(team) * personalPoints / team;
	}

	/**
	 * The raid level used for unique rolls: full up to 310, a third from 310 to 430, and a
	 * sixth above that.
	 */
	public static double toaScaledLevel(int raidLevel)
	{
		if (raidLevel <= 310)
		{
			return Math.max(0, raidLevel);
		}
		if (raidLevel <= 430)
		{
			return 310 + (raidLevel - 310) / 3.0;
		}
		return 350 + (raidLevel - 430) / 6.0;
	}

	/** Team points for 1% unique chance at this raid level: 10,500 - 20 x scaled level. */
	public static double toaPointsPerPercent(int raidLevel)
	{
		return 10_500 - 20 * toaScaledLevel(raidLevel);
	}

	/** The team's chance of a unique, capped at 55%. Points without the 5,000 starting points. */
	public static double toaTeamChance(double teamPoints, int raidLevel)
	{
		return Math.min(TOA_MAX_CHANCE, Math.max(0, teamPoints) / toaPointsPerPercent(raidLevel) / 100);
	}

	/**
	 * Your chance of a unique for one Tombs raid. Only one unique per raid; it goes to a
	 * player with a chance equal to their share of the points.
	 *
	 * @param personalPoints your points without the 5,000 starting points
	 * @param partyPoints    points the whole party earns once (puzzles); yours when solo
	 * @param teamPoints     the team total, 0 when unknown
	 * @param teamSize       players in the raid
	 * @return NaN when the points or raid level are unknown
	 */
	public static double toa(int personalPoints, int partyPoints, int teamPoints, int teamSize, int raidLevel)
	{
		if (personalPoints <= 0 || raidLevel < 0)
		{
			return Double.NaN;
		}
		if (teamSize <= 1)
		{
			return toaTeamChance(personalPoints + Math.max(0, partyPoints), raidLevel);
		}
		if (teamPoints > 0)
		{
			int team = Math.max(teamPoints, personalPoints);
			return toaTeamChance(team, raidLevel) * personalPoints / team;
		}
		// Team total unknown: below the 55% cap your share works out to your own points
		// over the points per percent, whatever the others did.
		return Math.min(TOA_MAX_CHANCE, personalPoints / toaPointsPerPercent(raidLevel) / 100);
	}

	/** How much of an item's normal share survives at this raid level (1, or 1/50 below its minimum). */
	public static double toaLevelFactor(int raidLevel, Integer minRaidLevel)
	{
		if (minRaidLevel == null || raidLevel < 0 || raidLevel >= minRaidLevel)
		{
			return 1;
		}
		return TOA_LOW_LEVEL_KEEP;
	}
}

