import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/** The dry-to-spooned scale in five bands, with a dot where you are. */
class LuckStrip extends JComponent
{
	static final double[] BANDS = {0, 0.1, 0.35, 0.65, 0.9, 1};
	private double luck = Double.NaN;

	LuckStrip()
	{
		setPreferredSize(new Dimension(80, 14));
		setOpaque(false);
	}

	void setLuck(double luck)
	{
		this.luck = luck;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth() - 8;
		int y = getHeight() / 2;
		for (int i = 0; i < BANDS.length - 1; i++)
		{
			double mid = (BANDS[i] + BANDS[i + 1]) / 2;
			g.setColor(Palette.blend(Palette.luck(mid), ColorScheme.DARKER_GRAY_COLOR, 0.35));
			int x0 = 4 + (int) Math.round(BANDS[i] * w);
			int x1 = 4 + (int) Math.round(BANDS[i + 1] * w);
			g.fillRect(x0, y - 2, x1 - x0, 4);
		}
		if (!Double.isNaN(luck))
		{
			int x = 4 + (int) Math.round(luck * w);
			g.setColor(Palette.luck(luck).brighter());
			g.fillOval(x - 4, y - 4, 9, 9);
			g.setColor(Color.WHITE);
			g.drawOval(x - 4, y - 4, 9, 9);
		}
		g.dispose();
	}
}

package com.expecteddrops.ui;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Luck colours: red (dry) to yellow to green (spooned), or orange to grey to blue for
 * colour-blind players.
 */
public final class Palette
{
	static final Color BAD = new Color(170, 40, 30);
	static final Color MID = new Color(170, 150, 20);
	static final Color GOOD = new Color(46, 160, 67);

	static final Color CB_BAD = new Color(220, 120, 20);
	static final Color CB_MID = new Color(140, 140, 140);
	static final Color CB_GOOD = new Color(40, 110, 200);

	private static volatile boolean colourBlind;

	private Palette()
	{
	}

	public static void setColourBlind(boolean on)
	{
		colourBlind = on;
	}

	/** Colour for a luck percentile 0..1 (grey when unknown). */
	public static Color luck(double luck)
	{
		if (Double.isNaN(luck))
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		Color bad = colourBlind ? CB_BAD : BAD;
		Color mid = colourBlind ? CB_MID : MID;
		Color good = colourBlind ? CB_GOOD : GOOD;
		if (luck < 0.5)
		{
			return blend(bad, mid, luck / 0.5);
		}
		return blend(mid, good, (luck - 0.5) / 0.5);
	}

	/** The "you have it" colour. */
	public static Color good()
	{
		return colourBlind ? CB_GOOD : GOOD;
	}

	static Color blend(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.expecteddrops.ui;

import java.awt.Color;
